function rc16T(k){return RC16_UI[rc11Lang()]?.[k]||RC16_UI.en[k]||k}
function rc16Settings(){const s=rc15Settings();
 if(!Array.isArray(s.documentationDepartments)||!s.documentationDepartments.length)s.documentationDepartments=RC14_DEPARTMENTS.map((name,i)=>({id:'dept-'+(i+1),name,icon:['◎','✦','⌁','◫','△','✚','↔','◉','⌘'][i]||'▦'}));
 s.knowledgeState=s.knowledgeState||{};if(!s.knowledgeState.language)s.knowledgeState.language='auto';
 s.communityGlobalProfessionalAccess=s.communityGlobalProfessionalAccess||{};
 s.googleDrive=s.googleDrive||{enabled:false,uploadProxyUrl:'',folderId:''};
 s.communityRegionFilter=s.communityRegionFilter||{};
 if(!s.v16Initialized){if(RC15_DOC_TYPES&&!RC15_DOC_TYPES.logo)RC15_DOC_TYPES.logo={label:'Company logo / brand image',required:false,accept:'image/*'};s.v16Initialized=true}
 return s}
function rc16RegionHue(regionId){const map={CARIBBEAN:191,USA:221,EUROPE:268,ASIA:14,OCEANIA:165,LATAM:340,CANADA:350};return map[regionId]??205}
function rc16RegionStyle(regionId){return`--region-hue:${rc16RegionHue(regionId)}`}
function rc16AccountImageDoc(accountId,account){const docs=rc14ProfileDocs(accountId);const pref=account?.profileImageMode||'portrait';return docs.filter(d=>(d.type||d.docType)===pref).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]||docs.filter(d=>(d.type||d.docType)==='portrait').sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]||docs.filter(d=>(d.type||d.docType)==='logo').sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]}
/* Fix legacy metadata mismatch: V14 stored `type`, early V15 read `docType`. */
rc15DocMeta=function(accountId,type){return rc14ProfileDocs(accountId).filter(d=>(d.type||d.docType)===type).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]};
rc15ProfilePhotoDoc=function(accountId){const c=(store.accounts||[]).find(x=>x.id===accountId);return rc16AccountImageDoc(accountId,c)};
function rc16AvatarHTML(p,size='normal'){const doc=p.imageDoc||null,initials=rc15Initials(p.name||p.company||'?');return`<span class="rc16-avatar-shell ${size}" style="${rc16RegionStyle(p.regionId)}">${doc?`<img data-rc16-avatar-doc="${rc15Escape(doc.id)}" alt="">`:`<span class="rc16-buddy">♟</span>`}<span class="rc16-initials">${rc15Escape(initials)}</span></span>`}
async function rc16HydrateAvatars(){for(const img of document.querySelectorAll('[data-rc16-avatar-doc]')){if(img.dataset.rc16Loaded)continue;try{const b=await rc14LoadBlob(img.dataset.rc16AvatarDoc);if(b){img.dataset.rc16Loaded='1';const u=URL.createObjectURL(b);img.src=u;img.onload=()=>setTimeout(()=>URL.revokeObjectURL(u),60000)}}catch(e){}}}
/* --- Country flags: actual emoji flags instead of country-code letter badges. --- */
const RC16_ISO3_2={DEU:'DE',BIH:'BA',HRV:'HR',ESP:'ES',IRL:'IE',GBR:'GB',SRB:'RS',SVN:'SI',MMR:'MM',VNM:'VN',AUS:'AU',CRI:'CR',SLV:'SV',MEX:'MX',CAN:'CA',AIA:'AI',ATG:'AG',BHS:'BS',BRB:'BB',DMA:'DM',JAM:'JM',KNA:'KN',PRI:'PR',VGB:'VG',VIR:'VI',SXM:'SX',GLP:'FR',MTQ:'FR',BLM:'FR'};
function rc16FlagEmoji(iso2){if(!iso2||iso2.length!==2)return'🌐';return [...iso2.toUpperCase()].map(c=>String.fromCodePoint(127397+c.charCodeAt(0))).join('')}
rc15FlagForTerritory=function(t){if(!t)return'🌐';if(t.regionId==='USA')return'🇺🇸';const c=String(t.code||'').toUpperCase(),mapped=RC16_ISO3_2[c];if(mapped)return rc16FlagEmoji(mapped);const n=String(t.name||'').toLowerCase();const names=[['saint-martin','FR'],['sint maarten','SX'],['guadeloupe','FR'],['martinique','FR'],['saint-barth','FR'],['barthélemy','FR'],['bahamas','BS'],['barbados','BB'],['barbade','BB'],['jamaica','JM'],['jamaïque','JM'],['anguilla','AI'],['antigua','AG'],['dominica','DM'],['dominique','DM'],['saint kitts','KN'],['puerto rico','PR'],['british virgin','VG'],['u.s. virgin','VI'],['germany','DE'],['allemagne','DE'],['bosnia','BA'],['croatia','HR'],['spain','ES'],['ireland','IE'],['united kingdom','GB'],['england','GB'],['serbia','RS'],['slovenia','SI'],['myanmar','MM'],['vietnam','VN'],['australia','AU'],['costa rica','CR'],['el salvador','SV'],['mexico','MX'],['canada','CA'],['france','FR'],['italy','IT'],['netherlands','NL'],['belgium','BE'],['switzerland','CH'],['brazil','BR'],['new zealand','NZ'],['japan','JP'],['singapore','SG'],['india','IN'],['south africa','ZA']];for(const[k,v]of names)if(n.includes(k))return rc16FlagEmoji(v);return'🌐'};
rc15HydrateRegionFlags=function(){document.querySelectorAll('[data-rc13-territory-open],[data-rc12-territory-detail]').forEach(b=>{const id=b.dataset.rc13TerritoryOpen||b.dataset.rc12TerritoryDetail,t=rc11Territory(id);if(!t)return;b.querySelectorAll('.rc15-country-flag,.rc16-territory-flag').forEach(x=>x.remove());b.insertAdjacentHTML('afterbegin',`<span class="rc16-territory-flag" title="${rc15Escape(t.name)}">${rc15FlagForTerritory(t)}</span>`)})};
/* --- Premium Community directory, visibility and direct-person interactions. --- */
function rc16CommunityIdentity(){if(rc15CommunityRole()==='admin'){const p=rc11AdminProfile(),acct=(store.accounts||[]).find(a=>a.adminProfileId===p?.id);return{id:'admin:'+p?.id,accountId:'admin:'+p?.id,name:p?.name||currentAccount()?.contact||'Administrator',company:p?.company||acct?.company||'',roleLabel:p?.jobTitle||rc11RoleLabel(p?.level),regionId:p?.regionId,territoryId:p?.territoryId,imageDoc:rc16AccountImageDoc('admin:'+p?.id,p),profile:p}}const c=currentClient();return{id:'pro:'+c?.id,accountId:c?.id,name:rcClientName(c)||c?.company||'Professional',company:c?.company||'',roleLabel:c?.clientType||c?.category||'Professional',regionId:c?.regionId,territoryId:c?.territoryId,imageDoc:rc16AccountImageDoc(c?.id,c),profile:c}}
rc15CommunityIdentity=rc16CommunityIdentity;
rc15CommunityDirectory=function(){const role=rc15CommunityRole(),me=rc16CommunityIdentity();if(role==='admin'){const p=rc11AdminProfile(),all=(store.adminProfiles||[]).filter(a=>a.active!==false);return all.filter(a=>rc15IsHQ(p)||rc12CanSeeTerritory(a.territoryId,p)||a.id===p?.id).map(a=>({id:'admin:'+a.id,accountId:'admin:'+a.id,name:a.name||a.email,company:a.company||'',roleLabel:a.jobTitle||rc11RoleLabel(a.level),subtitle:`${rc11RegionName(a.regionId)} · ${rc11Territory(a.territoryId)?.name||''}`,regionId:a.regionId,territoryId:a.territoryId,imageDoc:rc16AccountImageDoc('admin:'+a.id,a),profile:a}))}
 const c=currentClient(),global=!!c?.communityGlobalAccess,all=(store.accounts||[]).filter(a=>a.role==='client'&&a.active);return all.filter(x=>global||x.regionId===c?.regionId||x.id===c?.id).map(x=>({id:'pro:'+x.id,accountId:x.id,name:rcClientName(x)||x.company,company:x.company||'',roleLabel:x.clientType||x.category||'Professional',subtitle:`${x.company||''} · ${rc11RegionName(x.regionId)} · ${rc11Territory(x.territoryId)?.name||''}`,regionId:x.regionId,territoryId:x.territoryId,imageDoc:rc16AccountImageDoc(x.id,x),profile:x}))};
function rc16DirectoryPerson(id){return rc15CommunityDirectory().find(x=>x.id===id)||([rc16CommunityIdentity()].find(x=>x.id===id))}
function rc16EnsureDirectThread(personId){const role=rc15CommunityRole(),me=rc16CommunityIdentity(),dir=rc15CommunityDirectory(),other=dir.find(x=>x.id===personId);if(!other||other.id===me.id)return;const s=rc15Settings();let thread=s.communityThreads.find(t=>t.role===role&&t.kind==='direct'&&(t.participants||[]).includes(me.id)&&(t.participants||[]).includes(other.id));if(!thread){thread={id:rc11SafeId('thread'),role,kind:'direct',name:other.name,subtitle:`${other.roleLabel||''} · ${rc11RegionName(other.regionId)} · ${rc11Territory(other.territoryId)?.name||''}`,participants:[me.id,other.id],createdAt:new Date().toISOString()};s.communityThreads.unshift(thread)}s.communitySelected[role]=thread.id;saveStore();renderShell()}
function rc16PeopleDeck(role,me){const dir=rc15CommunityDirectory(),regions=[...new Set(dir.map(x=>x.regionId).filter(Boolean))],filter=rc16Settings().communityRegionFilter[role]||'';const shown=dir.filter(x=>!filter||x.regionId===filter);return`<section class="rc16-people-deck"><div class="rc16-people-deck-head"><div><h3>${rc16T('people')}</h3><p>${rc16T('peopleHelp')}</p></div><div class="rc16-people-filters"><input id="rc16PeopleSearch" placeholder="${rc16T('searchPeople')}"><select id="rc16PeopleRegion"><option value="">${rc16T('allRegions')}</option>${regions.map(r=>`<option value="${rc15Escape(r)}" ${filter===r?'selected':''}>${rc15Escape(rc11RegionName(r))}</option>`).join('')}</select></div></div><div class="rc16-people-orbit" id="rc16PeopleOrbit">${shown.filter(p=>p.id!==me.id).map(p=>`<article class="rc16-person-card" data-rc16-person="${rc15Escape(p.id)}" data-search="${rc15Escape((p.name+' '+p.company+' '+p.subtitle).toLowerCase())}" style="${rc16RegionStyle(p.regionId)}">${rc16AvatarHTML(p)}<div><b>${rc15Escape(p.name)}</b><small><span class="rc16-region-dot"></span>${rc15Escape(p.roleLabel||'')}</small><small>${rc15FlagForTerritory(rc11Territory(p.territoryId))} ${rc15Escape(rc11RegionName(p.regionId))} · ${rc15Escape(rc11Territory(p.territoryId)?.name||'')}</small></div></article>`).join('')||'<div style="color:#d7effb;padding:12px">No visible people.</div>'}</div></section>`}
function rc16ThreadAvatar(t,me){if(t.kind==='direct'){const other=(t.participants||[]).find(id=>id!==me.id),p=rc16DirectoryPerson(other);if(p)return rc16AvatarHTML(p)}return`<span class="rc16-avatar-shell" style="--region-hue:205"><span class="rc16-buddy">${t.id.includes('global')?'◎':'✦'}</span><span class="rc16-initials">${t.kind==='group'?'G':'C'}</span></span>`}
rc15CommunityHTML=function(){const role=rc15CommunityRole(),me=rc16CommunityIdentity(),threads=rc15Threads(),selected=rc15SelectedThread(),messages=selected?rc15ThreadMessages(selected.id):[],directory=rc15CommunityDirectory();const chatPerson=selected?.kind==='direct'?rc16DirectoryPerson((selected.participants||[]).find(id=>id!==me.id)):null;return rc11Hero(role==='admin'?rc16T('communityAdmin'):rc16T('communityTitle'),role==='admin'?rc16T('communityIntroAdmin'):rc16T('communityIntroPro'),'COMMUNITY INTELLIGENCE',`<button class="btn primary" id="rc15NewConversation">${rc16T('newGroup')}</button>`,[`${threads.length} thread(s)`])+`<div class="rc16-community-stage">${rc16PeopleDeck(role,me)}<div class="rc16-community-layout"><aside class="rc16-community-left"><div class="rc16-community-lefthead"><input id="rc15CommunitySearch" placeholder="${rc16T('searchPeople')}"><div class="rc15-compose-tools"><select id="rc15CommunityFilter"><option value="">${rc16T('allConversations')}</option><option value="group">${rc16T('groups')}</option><option value="direct">${rc16T('direct')}</option></select><select id="rc15CommunityDate"><option value="">All dates</option><option value="7">7 days</option><option value="30">30 days</option><option value="365">1 year</option></select><button class="btn secondary small" id="rc15CommunityArchiveToggle">${rc15Settings().communityShowArchives[role]?rc16T('active'):rc16T('archives')}</button></div></div><div class="rc16-thread-list">${threads.map(t=>{const last=rc15ThreadMessages(t.id).slice(-1)[0];return`<button class="rc16-thread ${selected?.id===t.id?'active':''}" data-rc15-thread="${rc15Escape(t.id)}" data-kind="${rc15Escape(t.kind||'group')}" data-search="${rc15Escape((t.name+' '+(t.subtitle||'')+' '+(last?.text||'')).toLowerCase())}" data-time="${last?new Date(last.createdAt).getTime():0}">${rc16ThreadAvatar(t,me)}<span class="rc16-thread-copy"><b>${rc15Escape(t.name)}</b><small>${rc15Escape(last?.text||t.subtitle||'No message yet')}</small></span><small class="rc16-thread-time">${last?new Date(last.createdAt).toLocaleDateString(rc11Lang()==='fr'?'fr-FR':rc11Lang()==='es'?'es-ES':'en-US'):''}</small></button>`}).join('')}</div></aside><main class="rc16-community-chat">${selected?`<header class="rc16-chat-head"><div class="rc16-chat-title">${chatPerson?rc16AvatarHTML(chatPerson):rc16ThreadAvatar(selected,me)}<div><b>${rc15Escape(selected.name)}</b><small>${rc15Escape(selected.subtitle||'Secure community thread')}</small>${chatPerson?`<div class="rc16-md-card"><span class="rc16-public-info">${rc15Escape(chatPerson.roleLabel||'')}</span><span class="rc16-public-info">${rc15FlagForTerritory(rc11Territory(chatPerson.territoryId))} ${rc15Escape(rc11RegionName(chatPerson.regionId))}</span>${role==='admin'&&rc15IsHQ()&&chatPerson.id.startsWith('admin:')?`<button class="btn secondary small" data-rc16-open-admin-dossier="${chatPerson.id.slice(6)}">${rc16T('openDossier')}</button>`:''}</div>`:''}</div></div><button class="btn secondary small" id="rc15ArchiveThread">${rc16T('archive')}</button></header><section class="rc16-chat-messages" id="rc15ChatMessages">${messages.map(m=>{const sp=rc16DirectoryPerson(m.senderId)||{id:m.senderId,name:m.senderName||'',regionId:m.regionId||'',territoryId:m.territoryId||'',imageDoc:null};return`<div class="rc16-msg-row ${m.senderId===me.id?'mine':''}" style="${rc16RegionStyle(sp.regionId)}">${rc16AvatarHTML(sp,'small')}<article class="rc16-msg"><div class="meta"><b>${rc15Escape(m.senderName)}</b><span class="rc16-region-badge" style="${rc16RegionStyle(sp.regionId)}">${rc15Escape(m.regionLabel||rc11RegionName(sp.regionId)||'')}</span><span>${new Date(m.createdAt).toLocaleString(rc11Lang()==='fr'?'fr-FR':rc11Lang()==='es'?'es-ES':'en-US')}</span></div><p>${rc15Escape(m.text||'')}</p>${m.link?`<div class="rc15-attachment"><span>🔗 ${rc15Escape(m.link)}</span><a href="${rc15Escape(m.link)}" target="_blank" rel="noopener">${rc16T('open')}</a></div>`:''}${m.fileId?`<div class="rc15-attachment"><span>▧ ${rc15Escape(m.fileName)} · ${Math.round((m.fileSize||0)/1024/1024*10)/10} MB</span><button class="btn secondary small" data-rc15-open-community-file="${rc15Escape(m.fileId)}">${rc16T('open')}</button></div>`:''}</article></div>`}).join('')||`<div class="rc12-empty">${rc16T('startConversation')}</div>`}</section><footer class="rc16-community-compose"><div class="rc16-compose-main"><textarea id="rc15MessageText" placeholder="${rc16T('write')}"></textarea><button class="btn primary" id="rc15SendMessage">${rc16T('send')}</button></div><div class="rc16-compose-meta"><input id="rc15MessageFile" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*,video/*"><input id="rc15MessageLink" type="text" placeholder="YouTube / cloud link"><span class="rc16-file-rule">${rc16T('filesRule')}</span></div></footer>`:`<div class="rc12-empty">${rc16T('noConversation')}</div>`}</main></div></div>`};
const rc16BaseBindCommunity=rc15BindCommunity;
rc15BindCommunity=function(){rc16BaseBindCommunity();document.querySelectorAll('[data-rc16-person]').forEach(card=>card.onclick=()=>rc16EnsureDirectThread(card.dataset.rc16Person));$('rc16PeopleSearch')?.addEventListener('input',()=>{const q=$('rc16PeopleSearch').value.toLowerCase();document.querySelectorAll('[data-rc16-person]').forEach(x=>x.style.display=!q||x.dataset.search.includes(q)?'grid':'none')});$('rc16PeopleRegion')?.addEventListener('change',e=>{rc16Settings().communityRegionFilter[rc15CommunityRole()]=e.target.value;saveStore();renderShell()});document.querySelectorAll('[data-rc16-open-admin-dossier]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(!rc15IsHQ())return toast(rc16T('noPermission'));rc13OpenAdminSheet(b.dataset.rc16OpenAdminDossier)});rc16HydrateAvatars()};
/* Make richer conversation creation easier to scan by region. */
rc15OpenNewConversation=function(){const role=rc15CommunityRole(),dir=rc15CommunityDirectory(),me=rc16CommunityIdentity(),regions=[...new Set(dir.map(x=>x.regionId).filter(Boolean))];showModal(`<div class="rc11-modal-wide"><h3>${rc16T('newGroup')}</h3><div class="rc12-modal-grid"><div class="field"><label>Conversation type</label><select id="rc15ConvType"><option value="direct">${rc16T('direct')}</option><option value="group">${rc16T('groups')}</option></select></div><div class="field"><label>${rc16T('region')}</label><select id="rc16ConvRegion"><option value="">${rc16T('allRegions')}</option>${regions.map(r=>`<option value="${r}">${rc15Escape(rc11RegionName(r))}</option>`).join('')}</select></div><div class="field full"><label>Group / subject name</label><input id="rc15ConvName" placeholder="Project, training cohort, region, subject…"></div></div><div class="rc16-people-orbit" id="rc16ConvPeople">${dir.filter(x=>x.id!==me.id).map(x=>`<label class="rc16-person-card" data-rc16-conv-card data-region="${x.regionId}" style="${rc16RegionStyle(x.regionId)}">${rc16AvatarHTML(x)}<div><input type="checkbox" data-rc15-conv-person="${rc15Escape(x.id)}"> <b>${rc15Escape(x.name)}</b><small>${rc15Escape(x.roleLabel||'')}</small><small>${rc15FlagForTerritory(rc11Territory(x.territoryId))} ${rc15Escape(x.subtitle)}</small></div></label>`).join('')}</div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${rc16T('cancel')}</button><button class="btn primary" id="rc15ConvCreate">Create</button></div></div>`);$('rc16ConvRegion').onchange=e=>document.querySelectorAll('[data-rc16-conv-card]').forEach(x=>x.style.display=!e.target.value||x.dataset.region===e.target.value?'grid':'none');$('rc15ConvCreate').onclick=()=>{const ids=[...document.querySelectorAll('[data-rc15-conv-person]:checked')].map(x=>x.dataset.rc15ConvPerson),kind=$('rc15ConvType').value;if(!ids.length)return toast('Select at least one participant.');if(kind==='direct'&&ids.length>1)return toast('Direct message: select one person only.');if(kind==='direct'){closeModal();return rc16EnsureDirectThread(ids[0])}const name=$('rc15ConvName').value.trim()||'New group',t={id:rc11SafeId('thread'),role,kind:'group',name,subtitle:`${ids.length+1} members`,participants:[me.id,...ids],createdAt:new Date().toISOString()};rc15Settings().communityThreads.unshift(t);rc15Settings().communitySelected[role]=t.id;saveStore();closeModal();renderShell();rc16HydrateAvatars()};setTimeout(rc16HydrateAvatars,0)};
/* --- Dynamic documentation departments, folders, languages and cross-document process journeys. --- */
function rc16DeptObjects(){return rc16Settings().documentationDepartments}
rc15DocDepartments=function(){return rc16DeptObjects().map(d=>d.name)};
function rc16DeptObjByName(name){return rc16DeptObjects().find(d=>d.name===name)||rc16DeptObjects()[0]}
function rc16LangLabel(v){return v==='fr'?'Français':v==='es'?'Español':v==='en'?'English':'All'}
function rc16KnowledgeLanguage(){const v=rc16Settings().knowledgeState.language||'auto';return v==='auto'?rc11Lang():v}
function rc16ProcessCompleted(d,progress){const steps=d.steps||[];return !!steps.length&&steps.every((_,i)=>progress?.[i])}
function rc16ProcessMap(docs,progress){const seq=docs.filter(d=>Number(d.processSequence)>0).slice().sort((a,b)=>Number(a.processSequence)-Number(b.processSequence));if(!seq.length)return'';let foundNext=false;return`<section class="rc16-process-map"><h4>${rc16T('processJourney')}</h4><div class="rc16-process-track">${seq.map(d=>{const done=rc16ProcessCompleted(d,progress[d.id]||{}),next=!done&&!foundNext;foundNext=foundNext||next;return`<article class="rc16-process-node ${done?'done':''} ${next?'next':''}" data-rc16-scroll-resource="${d.id}"><span class="n">${done?'✓':Number(d.processSequence)}</span><b>${rc15Escape(d.processName||d.title)}</b><small>${rc15Escape(d.title)}</small>${next?`<span class="rc16-lang-pill">${rc16T('nextAction')}</span>`:''}</article>`}).join('')}</div></section>`}
function rc16FolderCards(dept,docs,selected,admin,langMode){const folders=rc16Settings().documentationFolders.filter(f=>f.department===dept&&(langMode==='all'||!f.language||f.language==='all'||f.language===langMode));return`<div class="rc16-folder-grid"><article class="rc16-folder-card ${selected==='__all'?'active':''}" data-rc15-folder="__all"><b>▰ ${rc16T('allResources')}</b><small>${docs.filter(d=>d.department===dept).length} item(s)</small></article>${folders.map(f=>`<article class="rc16-folder-card ${selected===f.id?'active':''}" data-rc15-folder="${rc15Escape(f.id)}"><b>▰ ${rc15Escape(f.name)}</b><small>${docs.filter(d=>d.folderId===f.id).length} item(s)</small><span class="rc16-lang-pill">${rc16LangLabel(f.language||'all')}</span>${admin?`<button class="rc16-folder-edit" data-rc16-edit-folder="${f.id}" title="${rc16T('editFolder')}">⚙</button>`:''}</article>`).join('')}</div>`}
function rc16ResourceCard(d,progress,admin=false){const type=rc15ResourceType(d),done=rc16ProcessCompleted(d,progress);return`<article class="rc16-resource" id="rc16-res-${rc15Escape(d.id)}" data-rc15-resource data-dept="${rc15Escape(d.department)}" data-folder="${rc15Escape(d.folderId||'')}" data-search="${rc15Escape((d.title+' '+(d.description||'')+' '+type+' '+(d.processName||'')).toLowerCase())}"><span class="type">${rc15Escape(type)}</span><div class="rc16-resource-meta"><span>${rc16LangLabel(d.language||'all')}</span>${d.processSequence?`<span>#${Number(d.processSequence)} ${rc15Escape(d.processName||'Process')}</span>`:''}${d.priority?`<span>${rc15Escape(d.priority)}</span>`:''}</div><h3>${rc15Escape(d.title)}</h3><p>${rc15Escape(d.description||'')}</p><div class="toolbar">${d.url?`<a class="btn primary small" href="${rc15Escape(d.url)}" target="_blank" rel="noopener">${type==='YouTube'?'▶ '+rc16T('open'):rc16T('open')}</a>`:''}${d.fileId?`<button class="btn secondary small" data-rc14-open-doc="${rc15Escape(d.fileId)}">${rc16T('open')} ${rc15Escape(type)}</button>`:''}${admin?`<button class="btn danger small" data-rc15-delete-resource="${rc15Escape(d.id)}">${rc16T('delete')}</button>`:''}</div>${!admin?rc15WorkflowHTML(d,progress):d.steps?.length?`<div class="rc15-next-step"><b>${d.steps.length}-step process</b><br>${rc15Escape(d.steps[0])}</div>`:''}${done?`<div class="rc16-lang-pill">✓ ${rc16T('processComplete')}</div>`:''}</article>`}
rc15KnowledgeShell=function(docs,admin=false){const s=rc16Settings(),state=s.knowledgeState,departments=rc15DocDepartments(),dept=state.department&&departments.includes(state.department)?state.department:departments[0],folder=state.folder||'__all',progress=currentClient()?tenantData().docProgress||{}:{},langMode=admin?(state.language||'all'):rc16KnowledgeLanguage();if(admin&&state.language==='auto')state.language='all';const langOk=d=>langMode==='all'||!d.language||d.language==='all'||d.language===langMode,filtered=docs.filter(d=>d.department===dept&&langOk(d)&&(folder==='__all'||d.folderId===folder)),deptDocs=docs.filter(d=>d.department===dept&&langOk(d)),deptObj=rc16DeptObjByName(dept);return`<div class="rc16-knowledge-shell"><aside class="rc16-knowledge-rail"><div class="rc16-rail-title"><h4>${rc16T('departments')}</h4>${admin?`<button class="btn secondary small" data-rc16-manage-departments="1">⚙</button>`:''}</div><div class="rc16-dept-list">${rc16DeptObjects().map(x=>`<button class="rc16-dept-btn ${x.name===dept?'active':''}" data-rc15-dept="${rc15Escape(x.name)}"><span class="rc16-dept-icon">${rc15Escape(x.icon||'▦')}</span><span>${rc15Escape(x.name)}</span><span class="rc16-count">${docs.filter(d=>d.department===x.name).length}</span></button>`).join('')}</div></aside><main class="rc16-library-main"><div class="rc16-library-head"><div><span class="eyebrow">${admin?'KNOWLEDGE GOVERNANCE':'KNOWLEDGE HUB'}</span><h2>${rc15Escape(deptObj?.icon||'▦')} ${rc15Escape(dept)}</h2><p style="margin:0;color:#6d8193">${rc16T('foldersMedia')}</p></div>${admin?`<div class="rc16-library-actions"><button class="btn secondary" data-rc16-manage-departments="1">${rc16T('manageDepartments')}</button><button class="btn secondary" id="rc15AddFolder">${rc16T('newFolder')}</button><button class="btn primary" id="rc15AddResource">${rc16T('addResource')}</button></div>`:''}</div><div class="rc16-knowledge-tools"><input id="rc15KnowledgeSearch" placeholder="${rc16T('searchDocs')}"><select id="rc15KnowledgeType"><option value="">${rc16T('allFormats')}</option><option>PDF</option><option>Word</option><option>Excel</option><option>Video</option><option>YouTube</option><option>Link</option><option>Image</option></select><select id="rc16KnowledgeLanguage"><option value="all" ${langMode==='all'?'selected':''}>${rc16T('allLanguages')}</option><option value="en" ${langMode==='en'?'selected':''}>English</option><option value="fr" ${langMode==='fr'?'selected':''}>Français</option><option value="es" ${langMode==='es'?'selected':''}>Español</option></select></div>${rc16ProcessMap(deptDocs,progress)}${rc16FolderCards(dept,docs,folder,admin,langMode)}<div class="rc16-resource-grid" id="rc15ResourceGrid">${filtered.map(d=>rc16ResourceCard(d,progress[d.id]||{},admin)).join('')||'<div class="rc12-empty">No resource in this folder yet.</div>'}</div></main></div>`};
renderProfessionalDocumentationV14=function(){const c=currentClient(),docs=rc16Settings().documentationLibrary.filter(d=>rc15DocVisible(d,c));return rc11Hero(rc16T('knowledgeProTitle'),rc16T('knowledgeProIntro'),'PROFESSIONAL KNOWLEDGE','',[`${docs.length} resource(s)`])+rc15KnowledgeShell(docs,false)};
renderAdminDocumentationV14=function(){const docs=rc16Settings().documentationLibrary;return rc11Hero(rc16T('knowledgeAdminTitle'),rc16T('knowledgeAdminIntro'),'PREMIUM KNOWLEDGE GOVERNANCE','',[`${docs.length} resource(s)`])+rc15KnowledgeShell(docs,true)};
function rc16OpenDepartmentManager(){if(!isAdmin())return;const rows=rc16DeptObjects();showModal(`<div class="rc11-modal-wide"><h3>${rc16T('manageDepartments')}</h3><p>Only administrators can rename, add, reorder or remove documentation departments. Renaming synchronizes all folders and resources automatically.</p><div id="rc16DeptRows">${rows.map((d,i)=>`<div class="rc13-filter-row" data-rc16-dept-row="${d.id}" style="display:grid;grid-template-columns:70px 1fr auto;gap:8px;align-items:center;margin:7px 0"><input data-rc16-dept-icon="${d.id}" value="${rc15Escape(d.icon||'▦')}" maxlength="3"><input data-rc16-dept-name="${d.id}" value="${rc15Escape(d.name)}"><span><button class="btn secondary small" data-rc16-dept-up="${d.id}" ${i===0?'disabled':''}>↑</button> <button class="btn secondary small" data-rc16-dept-down="${d.id}" ${i===rows.length-1?'disabled':''}>↓</button> <button class="btn danger small" data-rc16-dept-delete="${d.id}">×</button></span></div>`).join('')}</div><div class="rc12-modal-grid" style="margin-top:12px"><div class="field"><label>${rc16T('icon')}</label><input id="rc16NewDeptIcon" value="▦"></div><div class="field"><label>${rc16T('departmentName')}</label><input id="rc16NewDeptName"></div></div><div class="toolbar"><button class="btn secondary" id="rc16AddDept">${rc16T('addDepartment')}</button><button class="btn secondary" onclick="closeModal()">${rc16T('cancel')}</button><button class="btn primary" id="rc16SaveDepts">${rc16T('save')}</button></div></div>`);const redraw=()=>{closeModal();rc16OpenDepartmentManager()};document.querySelectorAll('[data-rc16-dept-up]').forEach(b=>b.onclick=()=>{const i=rows.findIndex(x=>x.id===b.dataset.rc16DeptUp);if(i>0){[rows[i-1],rows[i]]=[rows[i],rows[i-1]];saveStore();redraw()}});document.querySelectorAll('[data-rc16-dept-down]').forEach(b=>b.onclick=()=>{const i=rows.findIndex(x=>x.id===b.dataset.rc16DeptDown);if(i>=0&&i<rows.length-1){[rows[i+1],rows[i]]=[rows[i],rows[i+1]];saveStore();redraw()}});document.querySelectorAll('[data-rc16-dept-delete]').forEach(b=>b.onclick=()=>{const d=rows.find(x=>x.id===b.dataset.rc16DeptDelete),used=rc16Settings().documentationLibrary.some(x=>x.department===d.name)||rc16Settings().documentationFolders.some(x=>x.department===d.name);if(used)return toast('Move or delete the department resources/folders first.');rc16Settings().documentationDepartments=rows.filter(x=>x.id!==d.id);saveStore();redraw()});$('rc16AddDept').onclick=()=>{const name=$('rc16NewDeptName').value.trim();if(!name)return;rows.push({id:rc11SafeId('dept'),name,icon:$('rc16NewDeptIcon').value.trim()||'▦'});saveStore();redraw()};$('rc16SaveDepts').onclick=()=>{rows.forEach(d=>{const old=d.name,newName=document.querySelector(`[data-rc16-dept-name="${d.id}"]`)?.value.trim()||old;d.icon=document.querySelector(`[data-rc16-dept-icon="${d.id}"]`)?.value.trim()||d.icon;if(newName!==old){rc16Settings().documentationLibrary.forEach(x=>{if(x.department===old)x.department=newName});rc16Settings().documentationFolders.forEach(x=>{if(x.department===old)x.department=newName});if(rc16Settings().knowledgeState.department===old)rc16Settings().knowledgeState.department=newName;d.name=newName}});saveStore();closeModal();renderShell();toast(rc16T('deptSaved'))}}
rc15OpenFolderEditor=function(folderId=''){const s=rc16Settings(),dept=s.knowledgeState?.department||rc15DocDepartments()[0],f=s.documentationFolders.find(x=>x.id===folderId);showModal(`<h3>${f?rc16T('editFolder'):rc16T('createFolder')}</h3><div class="field"><label>${rc16T('department')}</label><select id="rc15FolderDept">${rc15DocDepartments().map(x=>`<option ${x===(f?.department||dept)?'selected':''}>${rc15Escape(x)}</option>`).join('')}</select></div><div class="field"><label>${rc16T('folderName')}</label><input id="rc15FolderName" value="${rc15Escape(f?.name||'')}"></div><div class="field"><label>${rc16T('language')}</label><select id="rc16FolderLang"><option value="all" ${(f?.language||'all')==='all'?'selected':''}>${rc16T('allLanguages')}</option><option value="en" ${f?.language==='en'?'selected':''}>English</option><option value="fr" ${f?.language==='fr'?'selected':''}>Français</option><option value="es" ${f?.language==='es'?'selected':''}>Español</option></select></div><div class="toolbar"><button class="btn secondary" onclick="closeModal()">${rc16T('cancel')}</button>${f?`<button class="btn danger" id="rc16FolderDelete">${rc16T('delete')}</button>`:''}<button class="btn primary" id="rc15FolderSave">${rc16T('save')}</button></div>`);$('rc15FolderSave').onclick=()=>{const name=$('rc15FolderName').value.trim();if(!name)return toast('Folder name required.');if(f)Object.assign(f,{department:$('rc15FolderDept').value,name,language:$('rc16FolderLang').value});else s.documentationFolders.push({id:rc11SafeId('folder'),department:$('rc15FolderDept').value,name,language:$('rc16FolderLang').value,createdAt:new Date().toISOString()});saveStore();closeModal();renderShell();toast(rc16T('folderSaved'))};$('rc16FolderDelete')?.addEventListener('click',()=>{if(s.documentationLibrary.some(d=>d.folderId===f.id))return toast('This folder contains resources. Move or delete them first.');s.documentationFolders=s.documentationFolders.filter(x=>x.id!==f.id);saveStore();closeModal();renderShell()})};
