/* --- Calendar: admin-managed, professional read-only, localized monthly navigation. --- */
rc15CalendarHTML=function(admin=false){const cur=rc15CursorDate(),year=cur.getFullYear(),month=cur.getMonth(),firstDay=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),prevDays=new Date(year,month,0).getDate(),events=rc15CalendarEvents(admin),locale=rc11Lang()==='fr'?'fr-FR':rc11Lang()==='es'?'es-ES':'en-US',names=Array.from({length:7},(_,i)=>new Date(2026,0,5+i).toLocaleDateString(locale,{weekday:'short'})),cells=[];for(let i=0;i<42;i++){let day=i-firstDay+1,cd,muted=false;if(day<1){cd=new Date(year,month-1,prevDays+day);muted=true}else if(day>days){cd=new Date(year,month+1,day-days);muted=true}else cd=new Date(year,month,day);const dateKey=`${cd.getFullYear()}-${String(cd.getMonth()+1).padStart(2,'0')}-${String(cd.getDate()).padStart(2,'0')}`,evs=events.filter(e=>String(e.start||'').slice(0,10)===dateKey);cells.push(`<div class="rc15-day ${muted?'muted':''} ${admin?'admin':''}" ${admin&&!muted?`data-rc15-day="${dateKey}"`:''}><span class="rc15-day-no">${cd.getDate()}</span>${evs.slice(0,4).map(e=>`<button class="rc15-event-pill ${String(e.type||'').toLowerCase()}" data-rc15-event="${rc15Escape(e.id)}" title="${rc15Escape(e.title)}">${rc15Escape(e.title)}</button>`).join('')}${evs.length>4?`<small>+${evs.length-4}</small>`:''}</div>`)}const label=cur.toLocaleDateString(locale,{month:'long',year:'numeric'}),yearOptions=Array.from({length:10},(_,i)=>2026+i);return`<div class="rc15-calendar-wrap"><div class="rc15-calendar-toolbar"><div><span class="eyebrow">CALENDAR</span><div class="rc15-calendar-title">${rc15Escape(label)}</div>${!admin?`<div class="rc16-readonly-banner">${rc16T('readOnlyCalendar')}</div>`:''}</div><div class="toolbar"><select id="rc16CalMonth">${Array.from({length:12},(_,m)=>`<option value="${m}" ${m===month?'selected':''}>${new Date(2026,m,1).toLocaleDateString(locale,{month:'long'})}</option>`).join('')}</select><select id="rc16CalYear">${yearOptions.map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select><button class="btn secondary" id="rc15CalPrev">‹ ${rc16T('previous')}</button><button class="btn secondary" id="rc15CalToday">${rc16T('today')}</button><button class="btn secondary" id="rc15CalNext">${rc16T('next')} ›</button>${admin?`<button class="btn primary" id="rc15CalAdd">${rc16T('addEvent')}</button>`:''}</div></div><div class="rc15-calendar">${names.map(n=>`<div class="rc15-cal-head">${rc15Escape(n)}</div>`).join('')}${cells.join('')}</div></div>`};
