const rc16BaseDetectProject=detectProject;
detectProject=function(text,name){const a=rc16BaseDetectProject(text,name),line=(labels)=>{for(const label of labels){const r=new RegExp(label+'\\s*[:\\-]\\s*([^\\n\\r]{2,100})','i').exec(text);if(r?.[1])return r[1].trim()}return''};return{...a,firstName:line(['first name','prénom','prenom','nombre']),lastName:line(['last name','nom','apellido']),company:line(['company','société','societe','empresa'])||a.client,comment:line(['comment','comments','commentaire','notes chantier','site notes','observations']),client:a.client||line(['client','company','société','societe','empresa'])}};
applyDetected=function(a){if(a.systemId)form.systemId=a.systemId;if(a.areaM2){form.areaM2=a.areaM2;form.areaSqft=round2(a.areaM2*SQFT_PER_M2)}else if(a.areaSqft){form.areaSqft=a.areaSqft;form.areaM2=round2(a.areaSqft/SQFT_PER_M2)}if(a.company||a.client)form.client=a.company||a.client;if(a.project)form.project=a.project;if(a.comment)form.comment=a.comment;const t=tenantData();if(t)t.lastProjectSheet={...a,appliedAt:new Date().toISOString()};calculate();renderShell();toast(rc11Lang()==='fr'?'Fiche chantier appliquée au calculateur.':rc11Lang()==='es'?'Ficha de obra aplicada a la calculadora.':'Job sheet applied to the calculator.')};
analyzeFile=async function(file){if(!file)return;let text='';try{const ext=file.name.split('.').pop().toLowerCase(),buf=await file.arrayBuffer();if(ext==='docx')text=await extractDocx(buf);else if(ext==='xlsx')text=(await extractXlsx(buf)).flat().filter(Boolean).join('\n');else if(ext==='pdf')text=extractPdf(buf);else text=new TextDecoder().decode(buf);const a=detectProject(text,file.name);analyzedDocument={...a,fileName:file.name,text:text.slice(0,7000)};tenantData().documents.unshift({...analyzedDocument,createdAt:new Date().toISOString()});saveStore();$('documentAnalysis').innerHTML=`<div class="analysis-card"><h4>${rc11Lang()==='fr'?'Informations détectées':rc11Lang()==='es'?'Información detectada':'Detected information'}</h4><p><b>${rc16T('firstName')}:</b> ${esc(a.firstName||'—')}<br><b>${rc16T('lastName')}:</b> ${esc(a.lastName||'—')}<br><b>${rc16T('company')}:</b> ${esc(a.company||a.client||'—')}<br><b>${rc16T('system')}:</b> ${esc(a.systemName||'—')}<br><b>${rc16T('areaM2')}:</b> ${a.areaM2?num.format(a.areaM2):'—'} · <b>${rc16T('areaSqft')}:</b> ${a.areaSqft?num.format(a.areaSqft):'—'}<br><b>${rc16T('project')}:</b> ${esc(a.project||'—')}<br><b>${rc16T('comments')}:</b> ${esc(a.comment||'—')}</p><button class="btn primary" id="applyDocument">${rc11Lang()==='fr'?'Appliquer au calculateur':rc11Lang()==='es'?'Aplicar a la calculadora':'Apply to calculator'}</button>${!text.trim()?'<div class="notice warn" style="margin-top:10px">Scanned PDF / image text requires server OCR in production.</div>':''}</div>`;$('applyDocument').onclick=()=>applyDetected(a)}catch(e){$('documentAnalysis').innerHTML=`<div class="notice danger" style="margin-top:12px">${esc(e.message)}</div>`}};
