function rc16DrivePanel(){if(!isAdmin())return'';const g=rc16Settings().googleDrive;return`<section class="rc16-drive-panel"><div class="rc11-section-head"><div style="display:flex;gap:10px;align-items:center"><span class="rc16-drive-logo">D</span><div><span class="eyebrow">INTEGRATION</span><h3 style="margin:2px 0">${rc16T('driveTitle')}</h3><p>${rc16T('driveIntro')}</p></div></div></div><div class="rc12-modal-grid"><label class="permission-line full"><input id="rc16DriveEnabled" type="checkbox" ${g.enabled?'checked':''}> ${rc16T('enableDrive')}</label><div class="field full"><label>${rc16T('driveProxy')}</label><input id="rc16DriveProxy" value="${rc15Escape(g.uploadProxyUrl||'')}" placeholder="https://your-secure-backend.example/invoices/drive"></div><div class="field"><label>${rc16T('driveFolder')}</label><input id="rc16DriveFolder" value="${rc15Escape(g.folderId||'')}"></div></div><button class="btn primary" id="rc16SaveDrive">${rc16T('saveDrive')}</button></section>`}
const rc16BaseSettingsRenderer=renderSettingsV9;
renderSettingsV9=function(){return rc16BaseSettingsRenderer()+rc16DrivePanel()};
function rc16BindDriveSettings(){$('rc16SaveDrive')?.addEventListener('click',()=>{const g=rc16Settings().googleDrive;g.enabled=$('rc16DriveEnabled').checked;g.uploadProxyUrl=$('rc16DriveProxy').value.trim();g.folderId=$('rc16DriveFolder').value.trim();saveStore();toast(rc16T('driveSaved'))})}
async function rc16InvoiceToDrive(number){const g=rc16Settings().googleDrive;if(!g.enabled||!g.uploadProxyUrl)return toast(rc16T('driveNotConfigured'));const x=rc11FindInvoice(number);if(!x)return toast(rc16T('noPermission'));const html=document.querySelector('.modal-card .rc11-invoice-sheet')?.outerHTML||'';try{const r=await fetch(g.uploadProxyUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'store_invoice_pdf',invoice:x.invoice,client:x.client,html,folderId:g.folderId,requestedBy:currentAccount()?.email||''})});if(!r.ok)throw new Error('Drive connector error');toast('Invoice sent to Google Drive.')}catch(e){toast('Google Drive connector unavailable.')}}
async function rc16EmailInvoice(number){const x=rc11FindInvoice(number);if(!x)return;const to=x.invoice.email||x.client?.email||'',subject=`RENOVO CRETE — Invoice ${x.invoice.number}`,body=`Your finalized RENOVO CRETE invoice ${x.invoice.number} is available in your professional portal.\n\nOrder: ${x.invoice.orderNumber||''}\nTotal: ${rc11Money(x.invoice.totalEUR||0)}\n\nRENOVO CRETE`;const cfg=rc14Settings().transactionalEmail;if(cfg.proxyUrl){try{const html=document.querySelector('.modal-card .rc11-invoice-sheet')?.outerHTML||'';const r=await fetch(cfg.proxyUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'send_invoice',to,subject,body,invoice:x.invoice,html})});if(!r.ok)throw new Error('email');return toast('Invoice sent by email.')}catch(e){return toast('Email connector unavailable.')}}location.href=`mailto:${encodeURIComponent(to)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
const rc16BaseOpenInvoice=rc11OpenInvoice;
rc11OpenInvoice=function(number){rc16BaseOpenInvoice(number);setTimeout(()=>{const toolbar=document.querySelector('.modal-card .rc11-invoice-sheet .toolbar.rc11-no-print');if(!toolbar||toolbar.dataset.rc16)return;toolbar.dataset.rc16='1';toolbar.insertAdjacentHTML('afterbegin',`<button class="btn secondary" data-rc16-invoice-email="${rc15Escape(number)}">${rc16T('emailInvoice')}</button><button class="btn secondary" data-rc16-invoice-drive="${rc15Escape(number)}">${rc16T('saveToDrive')}</button>`);toolbar.querySelector('[data-rc16-invoice-email]').onclick=()=>rc16EmailInvoice(number);toolbar.querySelector('[data-rc16-invoice-drive]').onclick=()=>rc16InvoiceToDrive(number);rc16TranslateTree(document.querySelector('.modal-card'))},0)};
